 $inv | ConvertTo-Json -Depth 12 | Set-Content -LiteralPath (Join-Path $nativeOut 'inventory.json') -Encoding UTF8
 if($inv.assessment.serial_state -ne 'enumerated_not_opened' -or @($inv.assessment.serial_ports).Count -ne 1){throw 'Unique CH340 inventory required'}
 $nativeSerial=New-Object IO.Ports.SerialPort($inv.assessment.serial_ports[0],1500000,[IO.Ports.Parity]::None,8,[IO.Ports.StopBits]::One)
 $nativeSerial.DtrEnable=$false;$nativeSerial.RtsEnable=$false;$nativeSerial.Handshake=[IO.Ports.Handshake]::None
 $nativeSerial.ReadTimeout=40;$nativeSerial.WriteTimeout=1000;$nativeSerial.ReadBufferSize=1048576
 $nativeLog=[IO.File]::Open((Join-Path $nativeOut 'console.raw'),[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read)
 $nativeSerial.Open()
 Exit-FastbootNative
 if((Command-Native 'version') -notmatch '(?m)^U-Boot 2017\.09\b'){throw 'Fresh U-Boot version mismatch'}
 $c=$bootPlan.checks[0];$null=Require-CrcNative $c.address $c.bytes $c.crc32
 if($bootPlan.PSObject.Properties.Name -contains 'copy_intermediate'){
  $null=Command-Native $bootPlan.copy_intermediate
  $c=$bootPlan.intermediate_check;$null=Require-CrcNative $c.address $c.bytes $c.crc32
 }
 $null=Command-Native $bootPlan.copy_container
 foreach($i in @(1,2,3)){$c=$bootPlan.checks[$i];$null=Require-CrcNative $c.address $c.bytes $c.crc32}
 $null=Command-Native $bootPlan.copy_dtb
 $c=$bootPlan.checks[4];$null=Require-CrcNative $c.address $c.bytes $c.crc32
 if((Command-Native 'md.l 48300000 1') -notmatch '(?i)48300000:\s+edfe0dd0\b'){throw 'DTB magic mismatch'}
 $nativeReport.ram_crc_verified=$true;Save-Native
 Send-Native $bootPlan.bootm
 $reply=Read-Native 'VVBOOT alive elapsed_s=\d+ services_ready=1' 120
 if($reply -notmatch 'Booting Android Image' -or $reply -notmatch 'Starting kernel' -or $reply -match 'VVBOOT failed;|Wrong Image Format'){throw 'Boot markers failed'}
 Send-Native 'k7boot status'
 $status=Read-Native '(?m)(?:^|\n)nsh>[^\n]*$' 20
 if($status -notmatch 'VVBOOT stage=2\b' -or $status -notmatch 'logging=1\b'){throw 'Fresh boot status missing'}
 if($WaitPreviewReady){
  $previewObserved=$reply+"`n"+$status
  if($previewObserved -notmatch 'VOICE SESSION ready mode=0; awaiting explicit command'){
   $previewObserved+=Read-Native 'VOICE SESSION ready mode=0; awaiting explicit command' 60
  }
