  $nativeReport.initial_zero_held_preview_verified=$true
 }
 $nativeReport.status='ram_boot_passed';$nativeReport.ram_container_boot_tested=$true
} catch {$nativeReport.status='failed_or_uncertain';$nativeReport.error=$_.Exception.Message;throw}
finally {
 if($nativeSerial){if($nativeSerial.IsOpen){$nativeSerial.Close()};$nativeSerial.Dispose()}
 if($nativeLog){$nativeLog.Dispose()}
