{"status":"fulfilled","value":{"chunk_id":"cd69c7","wall_time_seconds":0.5423012,"exit_code":0,"original_token_count":2901,"output":"# Windows-only fresh quiescent proof; Execute alone reboots into idle Fastboot.
[CmdletBinding()]
param(
  [Alias('Mode')][ValidateSet('Check','Inventory','Audit','Execute')][string]$ResetMode='Check',
  [string]$Output='', [string]$DisplayStatus='', [string]$DisplaySha256='',
  [string]$CaptureStatus='', [string]$CaptureSha256='',
  [string]$PriorReport='', [string]$ReviewedSha256='',
  [ValidateSet('NeverStarted','StoppedDisplay')][string]$DisplayPolicy='NeverStarted',
  [ValidatePattern('^USB\\VID_1A86&PID_7523\\[A-Z0-9&]+$')]
  [string]$ExpectedSerialInstance='USB\VID_1A86&PID_7523\5&5F5591A&0&7'
)
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'k7_native_session.ps1')
$script:quiescentCaptureProof=$null
$script:quiescentCaptureLast=$null

function Normalize-Quiescent([string]$Text) {
  return ($Text -replace '\r+\n',"`n").Trim([char[]]"`r`n `0")
}
function Get-QuiescentProofUtc($Value) {
  if ($Value -is [DateTime]) {return $Value.ToUniversalTime()}
  return [DateTimeOffset]::Parse([string]$Value,[Globalization.CultureInfo]::InvariantCulture).UtcDateTime
}
function Get-QuiescentPromptPattern {
  # Read-Native removes ANSI but not heartbeats before matching. Permit only
  # complete source-format heartbeats after the prompt, never arbitrary text.
  return '(?:^|\n)nsh>[ \t]*(?:(?:\r*\n)?(?:'+(Get-QuiescentRadioHeartbeatPattern)+'|'+(Get-QuiescentRadioAckPattern)+'|VVBOOT alive elapsed_s=\d+ services_ready=1\r*\n))*$'
}
function Get-QuiescentRadioAckPattern {
  # Only the complete healthy two-line ACK observed in the reviewed raw logs.
  # A shared sequence is mandatory; single/partial lines and errors survive.
  return '(?-i:RADIO Wi-Fi RX type=1 id=15 seq=(?<quiescentAckSeq>[0-9]+) len=10\r*\n'+
    'RADIO Wi-Fi cmd=15 seq=\k<quiescentAckSeq> ack=1 status=0 response=0 ret=0\r*\n)'
}
function Get-QuiescentRadioHeartbeatPattern {
  # Exact k7boot/radio snapshot, including the unconfigured offline state.
  # It may immediately follow the prompt in the same serial read. Partial
  # groups and arbitrary errors are not accepted or stripped.
  $ip='(?:none|\d+(?:\.\d+){3})'
  return 'VVBOOT alive elapsed_s=\d+ services_ready=1\r*\n'+
    'WIFI status active=[01] wifi_connected=[01] ip='+$ip+' gateway='+$ip+' result=0\r*\n'+
    'WIFI frame_tx drops=\d+\r*\n'+
    'WIFI netdev rx=\d+ tx=\d+ dropped=\d+\r*\n'+
    'WIFI ARP rx_request=\d+ rx_reply=\d+ tx_request=\d+ tx_reply=\d+ wait_ms=250 retries=5\r*\n'+
    'WIFI AMSDU complete=\d+ subframes=\d+ rejected=\d+\r*\n'+
    'RADIO BLE name=VelaVision K7 connected=[01] handle=\d+ ACL_RX=\d+ ACL_TX_queued=\d+\r*\n'+
    'RADIO BLE history connections=\d+ disconnections=\d+ last_reason=\d+ encrypt_status=0 encrypted=[01]\r*\n'+
    'RADIO ble-status ret=0\r*\n'
}
function Get-QuiescentBody([string]$Reply,[string]$Command) {
  $clean=$Reply -replace '\x1b\[[0-9;]*[A-Za-z]',''
  if ($clean -match 'TRACK |PHOTO RAM|VOICE MODE applied=') {throw 'Preview/photo activity: not quiescent'}
  # Once per minute VVBOOT emits this exact read-only radio snapshot. It can
  # split a byte-paced command echo. Preserve raw evidence; remove only the
  # complete known-format block, never arbitrary WIFI/RADIO errors or text.
  $clean=$clean -creplace (Get-QuiescentRadioHeartbeatPattern),''
  $clean=$clean -creplace (Get-QuiescentRadioAckPattern),''
  $clean=$clean -replace 'VVBOOT alive elapsed_s=\d+ services_ready=1\r*\n',''
  # RX_MGMT metadata can interrupt a byte-paced echo even with preview stopped.
  # This header is not a success status. Keep all management/link error output;
  # remove only the complete type/id/length observed in the reviewed receipt.
  $clean=$clean -creplace 'RADIO Wi-Fi RX type=2 id=4 seq=[0-9]+ len=70\r*\n',''
  $clean=$clean -replace '\r+\n',"`n"
  $echo=$Command+"`n"
  $at=$clean.IndexOf($echo,[StringComparison]::Ordinal)
  if ($at -lt 0 -or $clean -notmatch '(?:^|\n)nsh>[ \t]*$') {throw 'Incomplete exact echo or final prompt'}
  $tail=$clean.Substring($at+$echo.Length)
  return Normalize-Quiescent $tail.Substring(0,$tail.LastIndexOf('nsh>'))
}
function Get-QuiescentPids([string]$Body) {
  $m=[regex]::Match($Body+"`n",'(?:^|\n)/proc:\n((?: [0-9]+/\n)+) fs/\n')
  if (-not $m.Success) {throw 'Incomplete proc PID section/fs marker'}
  $ids=@([regex]::Matches($m.Groups[1].Value,' ([0-9]+)/\n') | ForEach-Object {[int]$_.Groups[1].Value} | Sort-Object)
  if ($ids.Count -lt 8 -or $ids.Count -gt 64 -or @($ids | Select-Object -Unique).Count -ne $ids.Count) {throw 'Incomplete/duplicate task inventory'}
  return ,$ids
}
function Test-QuiescentNative([string]$Body) {
  $pattern='\AK7CLOUD native configured=0 running=0 stopping=[01] last_error=-?\d+\n(?:K7CLOUD native report_error=-?\d+ assessment_outcome=-?\d+ upload_attempted=[01] required_views=\d+ played_segments=\d+\n)?K7CLOUD native missing=platform_registration\nK7CLOUD native required=network,trusted_time,ca,entropy,endpoint,authentication,preview_pipeline,exclusive_owner,consent_and_request_metadata\z'
  if ($Body -notmatch $pattern) {throw 'Native state not fully stopped/unconfigured or receipt incomplete'}
}
function Test-StoppedDisplay([string]$Body) {
  foreach($pattern in @(
    '(?m)^K7DISPLAY attempted=1 started=0 error=0$',
    '(?m)^K7DISPLAY primary=0 cleanup=0 last_stop=0$',
    '(?m)^K7DISPLAY start_stage=\d+ cleanup_failures=0 panel_phase=\d+$',
    '(?m)^K7DISPLAY dma_stopped=1 lease=0 resource_stage=\d+$',
    '(?m)^K7DISPLAY resource_error=0 resource_cleanup=0$',
    '(?m)^K7DISPLAY video_frames=[1-9]\d* video_errors=0$',
    '(?m)^K7DISPLAY stop_stage=9 stop_error=0 stop_valid=f$'
  )){if($Body -cnotmatch $pattern){throw 'Display stopped proof incomplete or failed'}}
}
function Test-StoppedCapture([string]$Body) {
  $header='K7 CAPTURE attempted=1 active=0 stop_requested=1 result=0'
  if($Body -ceq $header){return} # Firmware before capture diagnostics.
  # 18k appends the completed producer stage and retained endpoint counters.
  # Accept this exact healthy structure, never discard arbitrary extra lines.
  $pattern='\A'+[regex]::Escape($header)+'\n'+
    'K7 CAPTURE_DIAG stage=9 banks=[0-9]+ packets=[0-9]+ bad=0 jpegs=[0-9]+ eof=[0-9]+ invalid=0 markers=[0-9]+ uvc_errors=0 bank_age_ms=[0-9]+ jpeg_age_ms=[0-9]+\n'+
    'UVC FLOW last_cc=(?<last>1|13) good=(?<good>[1-9][0-9]*) bad=0\n'+
    '(?:UVC FLOW_CC code=1 count=(?<success>[1-9][0-9]*)(?:\nUVC FLOW_CC code=13 count=(?<short>[1-9][0-9]*))?'+
    '|UVC FLOW_CC code=13 count=(?<short>[1-9][0-9]*))\z'
  $match=[regex]::Match($Body,$pattern)
  if(-not $match.Success){throw 'Capture service not successfully stopped or diagnostics incomplete'}
  [uint64]$success=0;[uint64]$short=0
  if($match.Groups['success'].Success){$success=[uint32]$match.Groups['success'].Value}
  if($match.Groups['short'].Success){$short=[uint32]$match.Groups['short'].Value}
  [uint64]$good=[uint32]$match.Groups['good'].Value
  if($success+$short -ne $good -or
     ($match.Groups['last'].Value -ceq '1' -and $success -eq 0) -or
     ($match.Groups['last'].Value -ceq '13' -and $short -eq 0)){
    throw 'Capture endpoint completion counters inconsistent'
  }
}
# Explicit reviewed historical counters are accepted only for the exact stopped
# diagnostic body. The ordinary Test-StoppedCapture zero-error policy is intact.
function Get-ReviewedCaptureRecord([string]$Body) {
  $healthy=$Body -creplace '(?<= invalid=)[0-9]+(?= markers=)','0'
  $healthy=$healthy -creplace '(?<= uvc_errors=)[0-9]+(?= bank_age_ms=)','0'
  Test-StoppedCapture $healthy
  $ages=[regex]::Match($Body,' bank_age_ms=(?<bank>[0-9]+) jpeg_age_ms=(?<jpeg>[0-9]+)\n')
  if(-not $ages.Success){throw 'Reviewed capture requires complete stage-9 diagnostics'}
  # These source fields are uint32 counters; only the two elapsed ages are u64.
  foreach($m in [regex]::Matches($Body,'(?:banks|packets|jpegs|eof|invalid|markers|uvc_errors)=(?<value>[0-9]+)')){
    [uint32]$checkedCounter=$m.Groups['value'].Value
  }
  [uint64]$bank=$ages.Groups['bank'].Value;[uint64]$jpeg=$ages.Groups['jpeg'].Value
  $normalized=$Body -creplace 'bank_age_ms=[0-9]+','bank_age_ms=<age>'
  $normalized=$normalized -creplace 'jpeg_age_ms=[0-9]+','jpeg_age_ms=<age>'
  return @{normalized_body=$normalized;bank_age_ms=$bank;jpeg_age_ms=$jpeg}
}
function Set-QuiescentCaptureProof([string]$Path,[string]$Sha256,[string]$Policy) {
  $script:quiescentCaptureProof=$null;$script:quiescentCaptureLast=$null
  if(-not $Path -and -not $Sha256){return}
  if(-not $Path -or $Sha256 -notmatch '\A[0-9a-fA-F]{64}\z' -or $Policy -cne 'StoppedDisplay'){
    throw 'CaptureStatus and exact CaptureSha256 require StoppedDisplay policy'
  }
  # Hash and parse the same bytes, so changing the file between reads cannot
  # substitute a different reviewed body. Status output contains ASCII only.
  $raw=[IO.File]::ReadAllBytes((Resolve-Path -LiteralPath $Path))
  $hash=[Security.Cryptography.SHA256]::Create()
# Explicit RAM staging only; never opens the serial port or writes storage.
[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$Manifest,
      [Parameter(Mandatory=$true)][string]$BuildProof,
      [Parameter(Mandatory=$true)][string]$Evidence)
$ErrorActionPreference='Stop'
