$package=Get-Content -LiteralPath $manifestPath -Raw -Encoding UTF8 | ConvertFrom-Json
$proof=Get-Content -LiteralPath $BuildProof -Raw -Encoding UTF8 | ConvertFrom-Json
if (-not $package.packaged -or $package.storage_written -or -not $proof.compiled -or
