    $proof.size -ne $package.kernel_bytes) {throw 'Candidate/build proof mismatch'}
if ((Get-Item -LiteralPath $imagePath).Length -ne $package.image_bytes -or
    (Get-FileHash -LiteralPath $imagePath -Algorithm SHA256).Hash -ine $package.image_sha256) {
  throw 'RAM image hash/size mismatch'
