  $limit=Invoke-FastbootNative @('-s','f71a9d152132db55','getvar','max-download-size') 'max-download-size'
  if ($limit -notmatch 'max-download-size:\s*0x0?7000000\b' -or $package.image_bytes -gt 117440512) {
